// Line-art data for the India → Taiwan journey story.
// Landmarks are drawn in local coordinates: centre x = 0, ground y = 0, up is negative.
// Each landmark is a list of separate strokes so they can draw one after another.

/* ---------------- Maps (simplified outlines from real lon/lat) ---------------- */

// India: outline traced from the official map (includes all of Jammu & Kashmir and Ladakh),
// scaled to 235 x 260 units. projIndia places cities with an affine fit
// calibrated on India's southern, western and eastern extremities.
const IX = [24.68641, -0.23718, -1638.268]
const IY = [-0.63537, -27.92652, 1117.413]
export const projIndia = (lon, lat) => [
  (IX[0] * lon + IX[1] * lat + IX[2] - 37.5) * 0.32581,
  (IY[0] * lon + IY[1] * lat + IY[2] - 44.5) * 0.32581,
]

