// Taiwan: 62 units per degree.
export const projTaiwan = (lon, lat) => [(lon - 119.9) * 62, (25.4 - lat) * 62]

const TAIWAN_OUTLINE = [
  [121.5, 25.3], [122.0, 25.0], [121.8, 24.5], [121.6, 23.5], [121.3, 22.8], [120.85, 21.9],
  [120.7, 22.3], [120.3, 22.6], [120.1, 23.0], [120.15, 23.7], [120.5, 24.4], [120.9, 24.9],
  [121.2, 25.1], [121.5, 25.3],
]

const toPath = (pts, proj) =>
  pts.map(([lon, lat], i) => {
    const [x, y] = proj(lon, lat)
    return `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`
  }).join(' ') + ' Z'

export const TAIWAN_PATH = toPath(TAIWAN_OUTLINE, projTaiwan)

