function howrah() {
  const strokes = [
    'M-130 0 Q-117 -5 -104 0 T-78 0 T-52 0 T-26 0 T0 0 T26 0 T52 0 T78 0 T104 0 T130 0',
    'M-130 -30 H130',
    'M-62 -30 V-140', 'M-50 -30 V-140', 'M50 -30 V-140', 'M62 -30 V-140',
    'M-66 -140 H-46', 'M46 -140 H66',
    'M-62 -30 V-8', 'M62 -30 V-8',
    'M-130 -30 L-56 -140 L0 -78 L56 -140 L130 -30',
  ]
  // Truss lattice: zigzag between the deck and the top chord.
  const chordY = (x) => {
    if (x <= -56) return -30 + ((x + 130) / 74) * -110
    if (x <= 0) return -140 + ((x + 56) / 56) * 62
    if (x <= 56) return -78 - (x / 56) * 62
    return -140 + ((x - 56) / 74) * 110
  }
  let d = ''
  for (let x = -122; x <= 122; x += 16) {
    const top = chordY(x + 8)
    d += `M${x} -30 L${x + 8} ${top.toFixed(1)} L${x + 16} -30 `
  }
  strokes.push(d.trim())
  return strokes
}
export const HOWRAH_BRIDGE = howrah()

function gopuram() {
  const strokes = ['M-80 0 H80', 'M-62 0 L-30 -150 H30 L62 0']
  for (let i = 1; i < 10; i++) {
    const y = -i * 15
    const half = 62 - 32 * (i * 15 / 150)
    strokes.push(`M${(-half).toFixed(1)} ${y} H${half.toFixed(1)}`)
  }
  strokes.push('M-14 0 V-34 H14 V0', 'M-36 -150 Q0 -180 36 -150', 'M-36 -150 H36')
  ;[-24, -12, 0, 12, 24].forEach((x) => strokes.push(`M${x} -${x === 0 ? 168 : 162} V-${x === 0 ? 180 : 172}`))
  return strokes
}
export const MEENAKSHI_GOPURAM = gopuram()

function pagoda() {
  const strokes = [
    'M-150 4 Q-138 0 -126 4 T-102 4 T-78 4 T-54 4 T-30 4 T-6 4 T18 4 T42 4 T66 4 T90 4 T114 4 T138 4',
    'M-150 -2 L-124 -34 L-104 -20 L-82 -46 L-58 -6', 'M56 -6 L80 -40 L100 -24 L124 -52 L150 -4',
    'M-56 -2 H56', 'M-44 -2 V-12 H44 V-2',
  ]
  let y = -12
  for (let i = 0; i < 9; i++) {
    const w = 30 - i * 2.4
    strokes.push(`M${(-w).toFixed(1)} ${y} V${y - 9} M${w.toFixed(1)} ${y} V${y - 9}`)
    strokes.push(`M${(-w - 10).toFixed(1)} ${y - 5} Q${(-w - 4).toFixed(1)} ${y - 9} ${(-w).toFixed(1)} ${y - 10} H${w.toFixed(1)} Q${(w + 4).toFixed(1)} ${y - 9} ${(w + 10).toFixed(1)} ${y - 5}`)
    y -= 14
  }
  strokes.push(`M0 ${y + 4} V${y - 22}`, `M-5 ${y - 6} H5`, `M-4 ${y - 14} H4`)
  return strokes
}
export const CIEN_PAGODA = pagoda()

